export function climbStairs(n: number): number {
  const memo = new Map<number, number>();
  function helper(i: number): number {
    if (i <= 2) {
      return i;
    }
    if (memo.has(i)) {
      return memo.get(i)!;
    }
    const result = helper(i - 1) + helper(i - 2);
    memo.set(i, result);
    return result;
  }
  return helper(n);
}
